277	  const whs={};ORDERS.filter(o=>o.a.includes("STUCK")).forEach(o=>whs[o.wh]=(whs[o.wh]||0)+1);
278	  const topWh=Object.keys(whs).sort((a,b)=>whs[b]-whs[a])[0]||"德国仓";
279	  $("#aiSummary").innerHTML=`<div class="ic">🤖</div><div class="txt">今日共 <b>${anom} 单</b>存在履约风险 —— 其中 <b>${over} 单已超时</b>、<span class="g">${stuck} 单卡在仓未出库</span>、<span class="g">${late} 单临近平台时效</span>。建议优先催 <b>${topWh}</b> 出库，并回填 Temu 运单号以免降权。<span style="color:var(--ink-3)">（点下方预警卡片可下钻）</span></div>`;
280	}
281	
282	// ---- anomaly rail ----
283	function renderRail(){
284	  const counts={};Object.keys(ANO).forEach(c=>counts[c]=ORDERS.filter(o=>o.a.includes(c)).length);
285	  $("#rail").innerHTML=Object.keys(ANO).map(c=>{
286	    const a=ANO[c];
287	    return `<div class="acard sev-${a.sev} ${F.anom===c?"on":""}" data-a="${c}" role="button" tabindex="0">
288	      <div class="an">${a.label}</div><div class="av mono">${counts[c]}</div><div class="ad">${a.desc}</div></div>`;
289	  }).join("");
290	  document.querySelectorAll(".acard").forEach(el=>{
291	    const h=()=>{F.anom=F.anom===el.dataset.a?null:el.dataset.a;render();};
292	    el.onclick=h;el.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();h();}};
293	  });
294	}
295	
296	// ---- presets & platforms ----
297	const PRESETS=[
298	  {t:"超时风险",f:o=>o.a.includes("LATE")},
299	  {t:"卡在仓",f:o=>o.a.includes("STUCK")},
300	  {t:"未回填运单",f:o=>o.a.includes("NOTRACK")},
301	  {t:"未同步ERP",f:o=>o.a.includes("NOSYNC")}
302	];
303	let activePreset=null;
304	function renderPresets(){
305	  $("#presets").innerHTML=PRESETS.map((p,i)=>`<button class="chip ${activePreset===i?"on":""}" data-p="${i}">${p.t}</button>`).join("");
306	  document.querySelectorAll("#presets .chip").forEach(el=>el.onclick=()=>{
307	    const i=+el.dataset.p;activePreset=activePreset===i?null:i;$("#nlInput").value=activePreset!==null?PRESETS[i].t:"";render();
308	  });
309	  $("#platforms").innerHTML=Object.keys(PF).map(p=>`<button class="chip pf ${F.pf===p?"on":""}" data-pf="${p}"><span class="pd" style="background:${PF[p].c}"></span>${p}</button>`).join("");
310	  document.querySelectorAll("#platforms .chip").forEach(el=>el.onclick=()=>{F.pf=F.pf===el.dataset.pf?null:el.dataset.pf;render();});
311	}
312	
313	// ---- table ----
314	function applyFilters(){
315	  return ORDERS.filter(o=>{
316	    if(F.onlyAnom&&!o.a.length)return false;
317	    if(F.anom&&!o.a.includes(F.anom))return false;
318	    if(F.pf&&o.pf!==F.pf)return false;
319	    if(activePreset!==null&&!PRESETS[activePreset].f(o))return false;
320	    if(F.q){
321	      const q=F.q.toLowerCase();
322	      const kw=[["超时","LATE"],["卡仓","STUCK"],["卡在仓","STUCK"],["运单","NOTRACK"],["回填","NOTRACK"],["同步","NOSYNC"],["库存","STOCK"]];
323	      let hit=false;
324	      kw.forEach(([k,c])=>{if(q.includes(k)&&o.a.includes(c))hit=true;});
325	      if(q.includes("temu")&&o.pf==="Temu")hit=true;
326	      if(q.includes("amazon")&&o.pf==="Amazon")hit=true;
327	      if(q.includes("仓")&&o.wh.includes(q.replace(/[的还在卡]/g,"").slice(0,2)))hit=true;
328	      if(o.sku.toLowerCase().includes(q)||o.id.toLowerCase().includes(q))hit=true;
329	      if(!hit)return false;
330	    }
331	    return true;
332	  });
333	}
334	function renderTable(){
335	  const rows=applyFilters();
336	  $("#rowCnt").textContent=rows.length+" / "+ORDERS.length+" 单";
337	  if(!rows.length){$("#tbody").innerHTML=`<tr><td colspan="10" class="empty">没有符合条件的订单 —— 试试点掉筛选或清空搜索</td></tr>`;return;}
338	  $("#tbody").innerHTML=rows.map(o=>{
339	    const sev=maxSev(o), r=fmtRemain(o.remain);
340	    const flags=o.a.map(c=>{const s=ANO[c].sev;return `<span class="flag ${s==="crit"?"c":s==="warn"?"w":"i"}">${ANO[c].label}</span>`;}).join("");
341	    return `<tr class="${sev?"sev-"+sev:""}">
342	      <td><div class="oid">${o.id}</div><div class="buyer">${o.buyer} · ${o.wh}</div></td>
343	      <td><div class="pf-cell"><span class="pd" style="background:${PF[o.pf].c}"></span>${o.pf}</div></td>
344	      <td><div class="sku" title="${o.sku}">${o.sku}</div></td>
345	      <td class="qty">×${o.qty}</td>
346	      <td>${o.remain===null?'<span class="pill g">已发货</span>':`<span class="clock ${r.cls}" data-remain="${o.remain}">${r.cls==="over"?"⚠ ":"⏱ "}${r.t}</span>`}</td>
347	      <td><span class="pill ${stateClass(o.p)}">${o.p}</span></td>
348	      <td><span class="pill ${stateClass(o.e)}">${o.e}</span></td>
349	      <td><span class="pill ${stateClass(o.w)}">${o.w}</span></td>
350	      <td>${o.track?`<span class="track">${o.track}</span>`:`<span class="track none">缺运单号</span>`}</td>
351	      <td><div class="flags">${flags||'<span style="color:var(--ink-3);font-size:.72rem">—</span>'}</div></td>
352	    </tr>`;
353	  }).join("");
354	}
355	
356	function render(){renderRail();renderPresets();renderTable();}
357	renderKPIs();renderAI();render();
358	
359	// nl input
360	let qt;$("#nlInput").addEventListener("input",e=>{clearTimeout(qt);qt=setTimeout(()=>{F.q=e.target.value.trim();if(!F.q)activePreset=activePreset;render();},160);});
361	// only-anomaly toggle
362	$("#onlyAnom").addEventListener("click",e=>{F.onlyAnom=!F.onlyAnom;e.currentTarget.classList.toggle("on",F.onlyAnom);e.currentTarget.setAttribute("aria-checked",F.onlyAnom);render();});
363	$("#onlyAnom").addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();$("#onlyAnom").click();}});
364	// export (demo)
365	$("#exportBtn").addEventListener("click",()=>{
366	  const rows=applyFilters().filter(o=>o.a.length);
367	  const head=["订单号","平台","SKU","数量","仓库","应发剩余分钟","平台状态","ERP状态","WMS状态","运单号","异常"];
368	  const lines=rows.map(o=>[o.id,o.pf,o.sku,o.qty,o.wh,o.remain===null?"":o.remain,o.p,o.e,o.w,o.track||"",o.a.map(c=>ANO[c].label).join("|")].join(","));
369	  const csv="﻿"+head.join(",")+"\n"+lines.join("\n");
370	  const blob=new Blob([csv],{type:"text/csv;charset=utf-8"});
371	  const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download="催发货清单_demo.csv";link.click();URL.revokeObjectURL(url);
372	});
373	
374	// live countdown tick
375	const reduce=window.matchMedia("(prefers-reduced-motion:reduce)").matches;
376	if(!reduce){
377	  setInterval(()=>{
378	    document.querySelectorAll(".clock[data-remain]").forEach(el=>{
379	      let m=+el.dataset.remain-(1/60);el.dataset.remain=m;
380	      const r=fmtRemain(Math.round(m));el.className="clock "+r.cls;el.textContent=(r.cls==="over"?"⚠ ":"⏱ ")+r.t;
381	    });
382	  },1000);
383	}
